// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // helper counterparty that always accepts the transferFrom call and returns success
    contract Accepting {
        // match selector transferFrom(address,address,uint256)
        function transferFrom(address, address, uint256) external pure returns (bool) {
            return true;
        }
    }

    // note: we cannot nest contract definitions in Foundry tests; move helper outside if needed
    function setUp() public { c = new C(); }

    // The test fuzzes: from address, array of recipients, and array of values
    // We cannot pass dynamic arrays directly as parameters to tests in some setups,
    // but Foundry supports fuzzing bytes/uint256 and addresses; here we use bytes to encode arrays
    // To keep it simple and fully fuzzed, we'll fuzz two uint256 values and an address and construct arrays.
    // However the requirement was to fuzz deciding values; we choose: address fromAddr, address callee, uint256 v0
    function testFuzz_property(address fromAddr, address calleeSeed, uint256 v0) public {
        // 1) ensure _tos length > 0 by constructing a single-element array
        address[] memory tos = new address[](1);
        uint[] memory vals = new uint[](1);

        // Deploy an accepting helper and use its address as the callee the contract will call.
        // The fuzzer still supplies calleeSeed but we must use a deployed contract for the external call to succeed
        Accepting helper = new Accepting();
        address helperAddr = address(helper);

        tos[0] = fromAddr; // put something admissible (fuzzer-chosen) as recipient
        // bound the value to a reasonable range but keep it wide
        vals[0] = bound(v0, 0, type(uint256).max);

        // Call transfer and capture its returned boolean via try/catch to observe returned value
        bool ok;
        try c.transfer(fromAddr, helperAddr, tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            // If it reverts, mark as false (but reference should only revert when _tos.length == 0 which we avoid)
            ok = false;
        }

        // The universal property: for any admissible input with non-empty _tos, reference C returns true.
        // Mutant that flips final return to false will make ok == false for successful calls; thus
        // assertTrue(ok) will pass on reference for all inputs and fail on mutant for some input.
        assertTrue(ok);
    }
}

// Minimal adversarial helper deployed above moved outside per solidity rules
contract Accepting {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an address for the 'from' actor and a positive length for the _tos/v arrays
    function testFuzz_property(address from, uint256 len) public {
        // keep len in a reasonable wide domain but non-zero (admissible domain requires _tos.length > 0)
        len = bound(len, 1, 8); // allow 1..8 entries

        // prepare arrays of addresses and values
        address[] memory tos = new address[](len);
        uint[] memory vals = new uint[](len);

        // Deploy an innocuous callee that will always succeed when called
        AlwaysAccept accept = new AlwaysAccept();

        for (uint i = 0; i < len; i++) {
            tos[i] = address(accept);
            vals[i] = uint256(i + 1);
        }

        // Call transfer and capture its boolean return via try/catch to observe non-revert behavior
        bool ok;
        try c.transfer(from, address(accept), tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            // if it reverts, mark as reverted (ok=false) - but reference C should not revert
            ok = false;
        }

        // GENERAL ASSERTION: For any admissible input where the external callee accepts the low-level calls,
        // the reference implementation returns true. The mutant returns false for the same successful execution,
        // so this assertion holds for the reference for all fuzz inputs and is violated by the mutant for some.
        assertTrue(ok);
    }
}

// Minimal adversarial helper that accepts low-level calls and returns normally
contract AlwaysAccept {
    fallback() external payable {
        // accept and return empty data (succeeds)
    }
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: from address and an array length + a boolean to decide whether the helper will revert
    function testFuzz_property(address from, bool willRevert, uint8 len) public {
        // domain: length must be > 0 to be admissible (require in transfer)
        // keep it wide otherwise
        vm.assume(len > 0);
        // deploy a helper that either reverts on calls or returns success
        ReverterOrOk helper = new ReverterOrOk(willRevert);

        // prepare arrays of addresses and values of length `len`
        address[] memory tos = new address[](len);
        uint[] memory vals = new uint[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(helper);
            vals[i] = uint256(1) + i; // arbitrary nonzero values
        }

        // Call transfer and observe whether it completes (does not revert)
        bool ok;
        try c.transfer(from, address(helper), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for any non-empty tos array, the reference contract will revert iff the callee reverts.
        // We assert that when the helper is set to revert (willRevert==true), the reference's transfer call must revert (ok==false).
        // This distinguishes the mutant which returns early and would make ok==true even when helper would revert.
        assertTrue(willRevert ? ok == false : ok == true);
    }
}

// adversarial helper: either reverts on any call or returns true
contract ReverterOrOk {
    bool public shouldRevert;
    constructor(bool _shouldRevert) { shouldRevert = _shouldRevert; }
    // emulate the expected selector: transferFrom(address,address,uint256)
    fallback() external payable {
        if (shouldRevert) revert("revert from helper");
        // otherwise do nothing (succeed)
    }
}
